	@Inject
	public EntityDslGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pInfrastructure = new InfrastructureElements();
		this.pResource = new ResourceElements();
		this.pComputeInstance = new ComputeInstanceElements();
		this.pStorageBucket = new StorageBucketElements();
		this.pNetwork = new NetworkElements();
		this.pVPC = new VPCElements();
		this.pHostedZone = new HostedZoneElements();
		this.pSubnet = new SubnetElements();
		this.eCloudProvider = new CloudProviderElements();
		this.eOSImage = new OSImageElements();
		this.eInstanceType = new InstanceTypeElements();
		this.eRegion = new RegionElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("co7217.week18.entity.EntityDsl".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
